#undef SYS_INNODB_BUFFER_STATS_BY_SCHEMA_FROM_SUFFIX
#undef SYS_INNODB_BUFFER_STATS_BY_SCHEMA_VIEW_DEFINITION
#undef SYS_X_INNODB_BUFFER_STATS_BY_SCHEMA_VIEW_DEFINITION

